/**
 * The recorded artefacts on disk, checked against the app that embeds them.
 *
 * `docs/media/` is generated by `scripts/record-demo.ts` and consumed by the Demo Video tab. A
 * stale recording is the failure mode that unit tests usually miss: the app renders fine, the
 * cards render fine, and only a human watching the video notices that scene two now shows
 * something else. These tests read the real files and compare them with the plan, so re-recording
 * after a UI change is enforced rather than remembered.
 *
 * They also keep the build honest: `vite.config.ts` publishes `*.webm` and `*.scenes.json` from
 * `docs/media`, so the names here are the contract between the recorder and the bundle.
 */

import { readFileSync, statSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

import {
  DEMO_CUE_SHEET_NAME,
  DEMO_VIDEO_NAME,
  parseCueSheet,
  type CueSheet,
} from "../src/demo/demoMedia";
import { RECORDING_SCENES } from "../src/demo/recordingPlan";

const HERE = dirname(fileURLToPath(import.meta.url));
const MEDIA_DIR = resolve(HERE, "..", "..", "..", "docs", "media");

function readCueSheet(): unknown {
  return JSON.parse(readFileSync(join(MEDIA_DIR, DEMO_CUE_SHEET_NAME), "utf8"));
}

describe("recorded walkthrough artefacts", () => {
  it("ships a playable WebM with the expected name", () => {
    const path = join(MEDIA_DIR, DEMO_VIDEO_NAME);
    const stats = statSync(path);
    expect(DEMO_VIDEO_NAME).toBe("harvestgrid-demo.webm");
    // A real VP8 recording of ~18 s at 1280×900 is hundreds of kB; anything tiny is a truncation.
    expect(stats.size).toBeGreaterThan(200_000);
    expect(stats.size).toBeLessThan(20_000_000);
    const header = readFileSync(path).subarray(0, 4);
    // EBML magic: the file really is a WebM container, not a renamed placeholder.
    expect([...header]).toEqual([0x1a, 0x45, 0xdf, 0xa3]);
  });

  it("has a cue sheet the app accepts, naming every scene in the plan", () => {
    const parsed: CueSheet | null = parseCueSheet(readCueSheet());
    expect(parsed, "cue sheet failed validation; re-record with scripts/record-demo.ts").not.toBeNull();
    const sheet = parsed as CueSheet;
    expect(sheet.video).toBe(DEMO_VIDEO_NAME);
    expect(sheet.scenes.map((scene) => scene.id)).toEqual(
      RECORDING_SCENES.map((scene) => scene.id),
    );
    // The card label is the plan's, so the tabs and the recording cannot disagree about names.
    expect(sheet.scenes.map((scene) => scene.cardTitle)).toEqual(
      RECORDING_SCENES.map((scene) => scene.cardTitle),
    );
    expect(sheet.scenes.map((scene) => scene.narration)).toEqual(
      RECORDING_SCENES.map((scene) => scene.narration),
    );
  });

  it("covers the whole video with contiguous, ordered scenes", () => {
    const sheet = parseCueSheet(readCueSheet()) as CueSheet;
    const first = sheet.scenes[0];
    const last = sheet.scenes[sheet.scenes.length - 1];
    expect(first?.startMs).toBeLessThan(5_000);
    // The recorder adds a closing beat after the last scene, so the tail is shorter than it.
    expect(sheet.durationMs).toBeGreaterThanOrEqual(last?.endMs ?? 0);
    expect(sheet.durationMs - (last?.endMs ?? 0)).toBeLessThanOrEqual(4_000);
    for (let index = 1; index < sheet.scenes.length; index += 1) {
      const previous = sheet.scenes[index - 1];
      const current = sheet.scenes[index];
      expect(current?.startMs).toBeGreaterThanOrEqual(previous?.endMs ?? 0);
      expect((current?.endMs ?? 0) - (current?.startMs ?? 0)).toBeGreaterThan(1_000);
    }
  });

  it("records the assertions the plan promised for each scene", () => {
    const sheet = parseCueSheet(readCueSheet()) as CueSheet;
    for (const scene of sheet.scenes) {
      const planned = RECORDING_SCENES.find((item) => item.id === scene.id);
      expect(planned, scene.id).toBeDefined();
      expect(scene.assertions ?? []).toHaveLength(planned?.expect.length ?? 0);
      for (const expectation of planned?.expect ?? []) {
        expect((scene.assertions ?? []).join(" ")).toContain(expectation.contains);
      }
    }
  });
});
